-- ============================================================
-- 242 · LAS FACTURAS DEL TALLER, LEÍDAS DE LOS PDF (Discom, iPark y Hergar)
-- ============================================================
-- Camilo, 12/11/2026: «me han pasado todas las facturas correspondientes […]
-- Los datos toca sacarlos por medio de los PDF […] En Hergar inventario pon
-- todo». Las carpetas Discom, Facturas de neumático y Hergar inventario.
--
-- CÓMO SE LEYERON: cada página pasada a imagen y leída de la IMAGEN (algunas
-- son escaneadas; en Discom la línea de matrícula y km ni siquiera está en el
-- texto del PDF). 571 páginas, 404 distintas, 339 facturas. Cada importe, fecha
-- y número se cruzó después con el texto del PDF donde lo había: cuadran todas
-- salvo cinco albaranes seguidos de iPark de julio, que la lectura desplazó de
-- uno a otro y se corrigieron con el texto. Los dos «Octubre.pdf» y
-- «septiembre.pdf» son el MISMO fichero: la factura de iPark de septiembre
-- (26/06140). La de octubre de iPark no estaba entre lo que se pasó.
--
-- LO QUE ENTRA: 329 facturas, 460 reparaciones de taller con
-- 2227 líneas, y 318 entradas de inventario de Hergar.
--   · Cada factura en «Facturas de taller». Las que ya estaban (mismo
--     proveedor y número) no se duplican: se les completa el coche de la línea
--     que estaba sin matrícula (las de Discom cargadas el 16/09 «sin matrícula
--     en el papel» la traían en la línea de la reparación).
--   · Cada reparación (Discom) o albarán (iPark) es un MANTENIMIENTO del coche,
--     con sus piezas y sus categorías, de origen 'factura'. No mueven el
--     semáforo de «le toca revisión»: ese cuenta solo lo apuntado a mano.
--   · Hergar: facturas «para el inventario» (no son NN) y cada línea, una
--     ENTRADA del artículo. Las facturas de Hergar que estaban apuntadas a
--     nombre de Discom (35241, 37219…) pasan a Hergar.
--
-- EL INVENTARIO SE MONTA EL 01/11/2026 (Camilo: «Pon la fecha como montada el
-- 01/11/2026, no hoy»): todas sus entradas llevan ese día, y el de la compra
-- en la nota de cada una.
--
-- LO QUE NO ENTRA (va en el Excel aparte, «Taller - facturas fuera de la
-- carga.xlsx»): las reparaciones con una matrícula que no está en Vehículos
-- (Camilo: «déjalas por fuera de la base de datos»), las facturas a otros
-- clientes (Formentera, Jataza, un particular) y los dos abonos. Al aplicarse se
-- vuelve a mirar: un coche que no exista en esta base tampoco entra.
--
-- Los importes, SIN IVA y en céntimos. Los km que Discom imprime como «1 Km»
-- (no los miró) van vacíos.

BEGIN;

CREATE TEMP TABLE _fac (k int, prov text, numero text, fecha date, base_cent int, iva_cent int, total_cent int, para_inv boolean, notas text) ON COMMIT DROP;

CREATE TEMP TABLE _rep (k int, fk int, referencia text, albaran text, fecha date, matricula text, km int, coste_cent int, concepto text, tipo text, categorias text[], descripcion text, hergar boolean) ON COMMIT DROP;

CREATE TEMP TABLE _pie (rk int, orden int, trabajo int, codigo text, descripcion text, cantidad numeric, precio_cent int, dto numeric, importe_cent int, categoria text) ON COMMIT DROP;

CREATE TEMP TABLE _mov (n int, fk int, albaran text, fecha date, destino text, codigo text, descripcion text, categoria text, cantidad numeric, precio_cent int, notas text) ON COMMIT DROP;

-- ── Los proveedores, por su NIF ─────────────────────────────────────────────
CREATE TEMP TABLE _prov ON COMMIT DROP AS
SELECT x.prov, p.id
  FROM (VALUES ('discom', 'B22522130'), ('ipark', 'A01516640'), ('hergar', 'A78009172')) AS x(prov, nif)
  JOIN taller_proveedor p ON upper(regexp_replace(p.nif, '[^A-Za-z0-9]', '', 'g')) = x.nif;

DO $$
BEGIN
  IF (SELECT count(*) FROM _prov) <> 3 THEN
    RAISE EXCEPTION 'Faltan proveedores (Discom, iPark o Hergar): ¿está aplicada db/241?';
  END IF;
END $$;

-- ── 1. Las de Hergar que se apuntaron a nombre de otro taller ──────────────
-- El 16/09 se cargaron facturas de Hergar (35241, 37219) como si fueran de
-- Discom. Si el número es el de una de Hergar y el total cuadra —o el número es
-- de cinco cifras, que en Discom no existe— pasa a Hergar y al inventario.
UPDATE factura_taller f
   SET proveedor_id = (SELECT id FROM _prov WHERE prov = 'hergar'),
       para_inventario = true
  FROM _fac s
 WHERE s.prov = 'hergar'
   AND f.anulado_at IS NULL
   AND f.proveedor_id <> (SELECT id FROM _prov WHERE prov = 'hergar')
   AND upper(btrim(f.numero)) = upper(s.numero)
   AND (f.total_cent = s.total_cent OR btrim(f.numero) ~ '^\d{5}$');

-- ── 2. Las facturas: las que ya estaban y las nuevas ───────────────────────
CREATE TEMP TABLE _fid ON COMMIT DROP AS
SELECT s.k, f.id, false AS nueva
  FROM _fac s
  JOIN _prov p ON p.prov = s.prov
  JOIN factura_taller f ON f.proveedor_id = p.id
                       AND upper(btrim(f.numero)) = upper(s.numero)
                       AND f.anulado_at IS NULL;

UPDATE factura_taller f SET para_inventario = true
  FROM _fid x JOIN _fac s ON s.k = x.k
 WHERE f.id = x.id AND s.para_inv AND NOT f.para_inventario;

WITH nuevas AS (
  SELECT p.id, s.numero, s.fecha, s.base_cent, s.iva_cent, s.total_cent, 'madrid', s.notas, s.para_inv
    FROM _fac s JOIN _prov p ON p.prov = s.prov
   WHERE NOT EXISTS (SELECT 1 FROM _fid x WHERE x.k = s.k)
  RETURNING id, proveedor_id, numero)
SELECT s.k, n.id, true
  FROM nuevas n
  JOIN _prov p ON p.id = n.proveedor_id
  JOIN _fac s  ON s.prov = p.prov AND s.numero = n.numero;

-- ── 3. El coche de cada reparación ─────────────────────────────────────────
-- Por la matrícula, también los de baja: es su historia. Sin coche, no entra.
CREATE TEMP TABLE _veh ON COMMIT DROP AS
SELECT r.k,
       (SELECT v.id FROM vehiculo v
         WHERE v.matricula_norm = r.matricula
         ORDER BY v.baja_at IS NOT NULL, v.id DESC LIMIT 1) AS vehiculo_id
  FROM _rep r
 WHERE NOT r.hergar;

-- ── 4. Las líneas de las facturas nuevas: una por reparación o albarán ─────
CREATE TEMP TABLE _lin (k int, linea_id bigint) ON COMMIT DROP;

WITH ins AS (
  SELECT fi.id, v.vehiculo_id, r.matricula, r.albaran, r.fecha, r.km, r.concepto, COALESCE(r.coste_cent, 0)
    FROM _rep r
    JOIN _fid fi ON fi.k = r.fk AND fi.nueva
    LEFT JOIN _veh v ON v.k = r.k
   WHERE r.hergar OR v.vehiculo_id IS NOT NULL
  RETURNING id, factura_id, albaran)
SELECT r.k, ins.id
  FROM ins
  JOIN _fid fi ON fi.id = ins.factura_id
  JOIN _rep r  ON r.fk = fi.k AND r.albaran IS NOT DISTINCT FROM ins.albaran;

-- ── 5. Las facturas que ya estaban: enlazar sus líneas ─────────────────────
-- Por el número de albarán (iPark los traía) …
SELECT r.k, l.id
  FROM _rep r
  JOIN _fid fi ON fi.k = r.fk AND NOT fi.nueva
  JOIN factura_taller_linea l
    ON l.factura_id = fi.id
   AND regexp_replace(COALESCE(l.albaran, ''), '\D', '', 'g') = regexp_replace(COALESCE(r.albaran, ''), '\D', '', 'g')
   AND regexp_replace(COALESCE(r.albaran, ''), '\D', '', 'g') <> ''
 WHERE NOT r.hergar;

-- … o, en una factura de una sola reparación, su única línea (Discom).
SELECT r.k, (SELECT l.id FROM factura_taller_linea l WHERE l.factura_id = fi.id)
  FROM _rep r
  JOIN _fid fi ON fi.k = r.fk AND NOT fi.nueva
 WHERE NOT r.hergar
   AND NOT EXISTS (SELECT 1 FROM _lin x WHERE x.k = r.k)
   AND (SELECT count(*) FROM factura_taller_linea l WHERE l.factura_id = fi.id) = 1
   AND (SELECT count(*) FROM _rep r2 WHERE r2.fk = r.fk) = 1;

-- La línea que estaba SIN coche se completa con el de la reparación. Si traía
-- otra matrícula escrita, no se toca: la puso alguien mirando el papel.
UPDATE factura_taller_linea l
   SET vehiculo_id     = v.vehiculo_id,
       matricula_texto = r.matricula,
       km              = COALESCE(l.km, r.km),
       fecha           = COALESCE(l.fecha, r.fecha),
       albaran         = COALESCE(l.albaran, r.albaran),
       concepto        = CASE WHEN COALESCE(btrim(l.concepto), '') IN ('', 'Ver factura', 'Material / taller')
                              THEN r.concepto ELSE l.concepto END
  FROM _lin x
  JOIN _rep r ON r.k = x.k
  JOIN _veh v ON v.k = r.k
 WHERE l.id = x.linea_id
   AND l.vehiculo_id IS NULL
   AND v.vehiculo_id IS NOT NULL
   AND (COALESCE(btrim(l.matricula_texto), '') = ''
        OR upper(regexp_replace(l.matricula_texto, '[^A-Za-z0-9]', '', 'g')) = r.matricula);

-- ── 6. Los mantenimientos: uno por reparación con coche ────────────────────
CREATE TEMP TABLE _man (k int, id bigint) ON COMMIT DROP;

WITH ins AS (
                             origen, proveedor_id, factura_id, factura_linea_id, referencia, categorias)
  SELECT v.vehiculo_id, r.tipo, r.fecha, r.km,
         CASE f.prov WHEN 'discom' THEN 'Discom' WHEN 'ipark' THEN 'iPark' END,
         GREATEST(r.coste_cent, 0), r.descripcion,
         'factura', p.id, fi.id, x.linea_id, r.referencia, r.categorias
    FROM _rep r
    JOIN _fac f  ON f.k = r.fk
    JOIN _prov p ON p.prov = f.prov
    JOIN _fid fi ON fi.k = r.fk
    JOIN _veh v  ON v.k = r.k AND v.vehiculo_id IS NOT NULL
    LEFT JOIN LATERAL (SELECT y.linea_id FROM _lin y WHERE y.k = r.k LIMIT 1) x ON true
   WHERE NOT r.hergar
     AND NOT EXISTS (SELECT 1 FROM mantenimiento m
                      WHERE m.factura_id = fi.id AND m.referencia IS NOT DISTINCT FROM r.referencia
                        AND m.anulado_at IS NULL)
     AND (x.linea_id IS NULL OR NOT EXISTS (SELECT 1 FROM mantenimiento m WHERE m.factura_linea_id = x.linea_id))
  RETURNING id, factura_id, referencia)
SELECT r.k, ins.id
  FROM ins
  JOIN _fid fi ON fi.id = ins.factura_id
  JOIN _rep r  ON r.fk = fi.k AND NOT r.hergar AND r.referencia IS NOT DISTINCT FROM ins.referencia;

-- ── 7. Sus piezas ──────────────────────────────────────────────────────────
                                 precio_cent, dto, importe_cent, categoria)
SELECT m.id, p.orden, p.trabajo, left(p.codigo, 48), p.descripcion, p.cantidad,
       p.precio_cent, p.dto, p.importe_cent, p.categoria
  FROM _pie p
  JOIN _man m ON m.k = p.rk;

-- ── 8. El inventario: los artículos de Hergar … ────────────────────────────
-- Uno por referencia (o por descripción si la línea no trae referencia), con la
-- descripción y el precio de su compra más reciente.
SELECT DISTINCT ON (COALESCE(upper(btrim(m.codigo)), '#' || upper(m.descripcion)))
       btrim(m.codigo), m.descripcion,
       CASE WHEN m.categoria IN ('mano_obra', 'nota') THEN 'otro' ELSE m.categoria END,
       (SELECT id FROM _prov WHERE prov = 'hergar'), m.precio_cent,
       'Alta con las facturas de Hergar (db/242)'
  FROM _mov m
 WHERE NOT EXISTS (
         SELECT 1 FROM inventario_articulo a
          WHERE (m.codigo IS NOT NULL AND upper(btrim(a.codigo)) = upper(btrim(m.codigo)))
             OR (m.codigo IS NULL AND a.codigo IS NULL AND upper(a.descripcion) = upper(m.descripcion)))
 ORDER BY COALESCE(upper(btrim(m.codigo)), '#' || upper(m.descripcion)), m.fecha DESC, m.n DESC;

-- … y cada línea, una entrada (una devolución, un ajuste a la baja).
SELECT a.id,
       CASE WHEN m.cantidad > 0 THEN 'entrada' ELSE 'ajuste' END,
       m.cantidad, m.fecha, m.precio_cent, fi.id, m.albaran, left(m.destino, 48),
       CASE WHEN m.cantidad > 0 THEN m.notas
            ELSE concat_ws(' · ', m.notas, 'Devolución en la factura ' || f.numero) END
  FROM _mov m
  JOIN _fac f  ON f.k = m.fk
  JOIN _fid fi ON fi.k = m.fk
  JOIN LATERAL (
        SELECT a.id FROM inventario_articulo a
         WHERE (m.codigo IS NOT NULL AND upper(btrim(a.codigo)) = upper(btrim(m.codigo)))
            OR (m.codigo IS NULL AND a.codigo IS NULL AND upper(a.descripcion) = upper(m.descripcion))
         ORDER BY a.id LIMIT 1) a ON true
 WHERE NOT EXISTS (SELECT 1 FROM inventario_movimiento x
                    WHERE x.factura_id = fi.id AND x.articulo_id = a.id
                      AND x.albaran IS NOT DISTINCT FROM m.albaran AND x.cantidad = m.cantidad);

-- El último precio de cada artículo, el de su entrada más reciente.
UPDATE inventario_articulo a
   SET ultimo_precio_cent = u.precio_cent
  FROM (SELECT DISTINCT ON (articulo_id) articulo_id, precio_cent
          FROM inventario_movimiento
         WHERE tipo = 'entrada' AND anulado_at IS NULL AND precio_cent IS NOT NULL
         ORDER BY articulo_id, fecha DESC, id DESC) u
 WHERE a.id = u.articulo_id;

COMMIT;
